    GetScalingPlanResourceForecastDataRequest.add_member(:scaling_plan_name, Smithy::Schema::Shapes::ShapeRef.new(shape: ScalingPlanName, location_name: 'ScalingPlanName', traits: {"smithy.api#documentation" => "<p>The name of the scaling plan.</p>", "smithy.api#required" => {}}))
    GetScalingPlanResourceForecastDataRequest.add_member(:scaling_plan_version, Smithy::Schema::Shapes::ShapeRef.new(shape: ScalingPlanVersion, location_name: 'ScalingPlanVersion', traits: {"smithy.api#documentation" => "<p>The version number of the scaling plan. Currently, the only valid value is\n            <code>1</code>.</p>", "smithy.api#required" => {}}))
    GetScalingPlanResourceForecastDataRequest.add_member(:service_namespace, Smithy::Schema::Shapes::ShapeRef.new(shape: ServiceNamespace, location_name: 'ServiceNamespace', traits: {"smithy.api#documentation" => "<p>The namespace of the AWS service. The only valid value is <code>autoscaling</code>.\n      </p>", "smithy.api#required" => {}}))
    GetScalingPlanResourceForecastDataRequest.add_member(:resource_id, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlString, location_name: 'ResourceId', traits: {"smithy.api#documentation" => "<p>The ID of the resource. This string consists of a prefix (<code>autoScalingGroup</code>)\n         followed by the name of a specified Auto Scaling group (<code>my-asg</code>). Example:\n            <code>autoScalingGroup/my-asg</code>. </p>", "smithy.api#required" => {}}))
    GetScalingPlanResourceForecastDataRequest.add_member(:scalable_dimension, Smithy::Schema::Shapes::ShapeRef.new(shape: ScalableDimension, location_name: 'ScalableDimension', traits: {"smithy.api#documentation" => "<p>The scalable dimension for the resource. The only valid value is\n            <code>autoscaling:autoScalingGroup:DesiredCapacity</code>. </p>", "smithy.api#required" => {}}))
    GetScalingPlanResourceForecastDataRequest.add_member(:forecast_data_type, Smithy::Schema::Shapes::ShapeRef.new(shape: ForecastDataType, location_name: 'ForecastDataType', traits: {"smithy.api#documentation" => "<p>The type of forecast data to get.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>LoadForecast</code>: The load metric forecast. </p>\n            </li>\n            <li>\n               <p>\n                  <code>CapacityForecast</code>: The capacity forecast. </p>\n            </li>\n            <li>\n               <p>\n                  <code>ScheduledActionMinCapacity</code>: The minimum capacity for each scheduled\n               scaling action. This data is calculated as the larger of two values: the capacity\n               forecast or the minimum capacity in the scaling instruction.</p>\n            </li>\n            <li>\n               <p>\n                  <code>ScheduledActionMaxCapacity</code>: The maximum capacity for each scheduled\n               scaling action. The calculation used is determined by the predictive scaling maximum\n               capacity behavior setting in the scaling instruction.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    GetScalingPlanResourceForecastDataRequest.add_member(:start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: TimestampType, location_name: 'StartTime', traits: {"smithy.api#documentation" => "<p>The inclusive start time of the time range for the forecast data to get. The date and\n         time can be at most 56 days before the current date and time. </p>", "smithy.api#required" => {}}))
    GetScalingPlanResourceForecastDataRequest.add_member(:end_time, Smithy::Schema::Shapes::ShapeRef.new(shape: TimestampType, location_name: 'EndTime', traits: {"smithy.api#documentation" => "<p>The exclusive end time of the time range for the forecast data to get. The maximum time\n         duration between the start and end time is seven days. </p>\n         <p>Although this parameter can accept a date and time that is more than two days in the\n         future, the availability of forecast data has limits. AWS Auto Scaling only issues forecasts for\n         periods of two days in advance.</p>", "smithy.api#required" => {}}))
    GetScalingPlanResourceForecastDataRequest.type = Types::GetScalingPlanResourceForecastDataRequest
