    PolicyType.add_member(:target_tracking_scaling, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'TargetTrackingScaling', traits: {"smithy.api#enumValue" => "TargetTrackingScaling"}))
    PredefinedLoadMetricSpecification.add_member(:predefined_load_metric_type, Smithy::Schema::Shapes::ShapeRef.new(shape: LoadMetricType, location_name: 'PredefinedLoadMetricType', traits: {"smithy.api#documentation" => "<p>The metric type.</p>", "smithy.api#required" => {}}))
    PredefinedLoadMetricSpecification.add_member(:resource_label, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceLabel, location_name: 'ResourceLabel', traits: {"smithy.api#documentation" => "<p>Identifies the resource associated with the metric type. You can't specify a resource\n         label unless the metric type is <code>ALBTargetGroupRequestCount</code> and there is a\n         target group for an Application Load Balancer attached to the Auto Scaling group.</p>\n         <p>You create the resource label by appending the final portion of the load balancer ARN\n         and the final portion of the target group ARN into a single value, separated by a forward\n         slash (/). The format is\n         app/<load-balancer-name>/<load-balancer-id>/targetgroup/<target-group-name>/<target-group-id>,\n         where:</p>\n         <ul>\n            <li>\n               <p>app/<load-balancer-name>/<load-balancer-id> is the final portion of\n               the load balancer ARN</p>\n            </li>\n            <li>\n               <p>targetgroup/<target-group-name>/<target-group-id> is the final portion\n               of the target group ARN.</p>\n            </li>\n         </ul>\n         <p>This is an example:\n         app/EC2Co-EcsEl-1TKLTMITMM0EO/f37c06a68c1748aa/targetgroup/EC2Co-Defau-LDNM7Q3ZH1ZN/6d4ea56ca2d6a18d.</p>\n         <p>To find the ARN for an Application Load Balancer, use the <a href=\"https://docs.aws.amazon.com/elasticloadbalancing/latest/APIReference/API_DescribeLoadBalancers.html\">DescribeLoadBalancers</a> API operation. To find the ARN for the target group, use\n         the <a href=\"https://docs.aws.amazon.com/elasticloadbalancing/latest/APIReference/API_DescribeTargetGroups.html\">DescribeTargetGroups</a> API operation.</p>"}))
    PredefinedLoadMetricSpecification.type = Types::PredefinedLoadMetricSpecification
    PredefinedScalingMetricSpecification.add_member(:predefined_scaling_metric_type, Smithy::Schema::Shapes::ShapeRef.new(shape: ScalingMetricType, location_name: 'PredefinedScalingMetricType', traits: {"smithy.api#documentation" => "<p>The metric type. The <code>ALBRequestCountPerTarget</code> metric type applies only to\n         Auto Scaling groups, Spot Fleet requests, and ECS services.</p>", "smithy.api#required" => {}}))
    PredefinedScalingMetricSpecification.add_member(:resource_label, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceLabel, location_name: 'ResourceLabel', traits: {"smithy.api#documentation" => "<p>Identifies the resource associated with the metric type. You can't specify a resource\n         label unless the metric type is <code>ALBRequestCountPerTarget</code> and there is a target\n         group for an Application Load Balancer attached to the Auto Scaling group, Spot Fleet request, or\n         ECS service.</p>\n         <p>You create the resource label by appending the final portion of the load balancer ARN\n         and the final portion of the target group ARN into a single value, separated by a forward\n         slash (/). The format is\n         app/<load-balancer-name>/<load-balancer-id>/targetgroup/<target-group-name>/<target-group-id>,\n         where:</p>\n         <ul>\n            <li>\n               <p>app/<load-balancer-name>/<load-balancer-id> is the final portion of\n               the load balancer ARN</p>\n            </li>\n            <li>\n               <p>targetgroup/<target-group-name>/<target-group-id> is the final portion\n               of the target group ARN.</p>\n            </li>\n         </ul>\n         <p>This is an example:\n         app/EC2Co-EcsEl-1TKLTMITMM0EO/f37c06a68c1748aa/targetgroup/EC2Co-Defau-LDNM7Q3ZH1ZN/6d4ea56ca2d6a18d.</p>\n         <p>To find the ARN for an Application Load Balancer, use the <a href=\"https://docs.aws.amazon.com/elasticloadbalancing/latest/APIReference/API_DescribeLoadBalancers.html\">DescribeLoadBalancers</a> API operation. To find the ARN for the target group, use\n         the <a href=\"https://docs.aws.amazon.com/elasticloadbalancing/latest/APIReference/API_DescribeTargetGroups.html\">DescribeTargetGroups</a> API operation.</p>"}))
    PredefinedScalingMetricSpecification.type = Types::PredefinedScalingMetricSpecification
    PredictiveScalingMaxCapacityBehavior.add_member(:set_forecast_capacity_to_max_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'SetForecastCapacityToMaxCapacity', traits: {"smithy.api#enumValue" => "SetForecastCapacityToMaxCapacity"}))
    PredictiveScalingMaxCapacityBehavior.add_member(:set_max_capacity_to_forecast_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'SetMaxCapacityToForecastCapacity', traits: {"smithy.api#enumValue" => "SetMaxCapacityToForecastCapacity"}))
    PredictiveScalingMaxCapacityBehavior.add_member(:set_max_capacity_above_forecast_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'SetMaxCapacityAboveForecastCapacity', traits: {"smithy.api#enumValue" => "SetMaxCapacityAboveForecastCapacity"}))
