    PredictiveScalingMode.add_member(:forecast_only, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'ForecastOnly', traits: {"smithy.api#enumValue" => "ForecastOnly"}))
    ScalableDimension.add_member(:auto_scaling_group_desired_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'AutoScalingGroupDesiredCapacity', traits: {"smithy.api#enumValue" => "autoscaling:autoScalingGroup:DesiredCapacity"}))
    ScalableDimension.add_member(:ecs_service_desired_count, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'ECSServiceDesiredCount', traits: {"smithy.api#enumValue" => "ecs:service:DesiredCount"}))
    ScalableDimension.add_member(:ec2_spot_fleet_request_target_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'EC2SpotFleetRequestTargetCapacity', traits: {"smithy.api#enumValue" => "ec2:spot-fleet-request:TargetCapacity"}))
    ScalableDimension.add_member(:rds_cluster_read_replica_count, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'RDSClusterReadReplicaCount', traits: {"smithy.api#enumValue" => "rds:cluster:ReadReplicaCount"}))
    ScalableDimension.add_member(:dynamo_db_table_read_capacity_units, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'DynamoDBTableReadCapacityUnits', traits: {"smithy.api#enumValue" => "dynamodb:table:ReadCapacityUnits"}))
    ScalableDimension.add_member(:dynamo_db_table_write_capacity_units, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'DynamoDBTableWriteCapacityUnits', traits: {"smithy.api#enumValue" => "dynamodb:table:WriteCapacityUnits"}))
    ScalableDimension.add_member(:dynamo_db_index_read_capacity_units, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'DynamoDBIndexReadCapacityUnits', traits: {"smithy.api#enumValue" => "dynamodb:index:ReadCapacityUnits"}))
    ScalableDimension.add_member(:dynamo_db_index_write_capacity_units, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'DynamoDBIndexWriteCapacityUnits', traits: {"smithy.api#enumValue" => "dynamodb:index:WriteCapacityUnits"}))
    ScalingInstruction.add_member(:service_namespace, Smithy::Schema::Shapes::ShapeRef.new(shape: ServiceNamespace, location_name: 'ServiceNamespace', traits: {"smithy.api#documentation" => "<p>The namespace of the AWS service.</p>", "smithy.api#required" => {}}))
    ScalingInstruction.add_member(:resource_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceIdMaxLen1600, location_name: 'ResourceId', traits: {"smithy.api#documentation" => "<p>The ID of the resource. This string consists of the resource type and unique\n         identifier.</p> \n         <ul>\n            <li>\n               <p>Auto Scaling group - The resource type is <code>autoScalingGroup</code> and the unique identifier is the\n               name of the Auto Scaling group. Example: <code>autoScalingGroup/my-asg</code>.</p>\n           </li>\n            <li>\n               <p>ECS service - The resource type is <code>service</code> and the unique identifier is the cluster name  \n               and service name. Example: <code>service/default/sample-webapp</code>.</p>\n           </li>\n            <li>\n               <p>Spot Fleet request - The resource type is <code>spot-fleet-request</code> and the unique identifier is the \n               Spot Fleet request ID. Example: <code>spot-fleet-request/sfr-73fbd2ce-aa30-494c-8788-1cee4EXAMPLE</code>.</p>\n           </li>\n            <li>\n               <p>DynamoDB table - The resource type is <code>table</code> and the unique identifier is the resource ID. \n               Example: <code>table/my-table</code>.</p>\n           </li>\n            <li>\n               <p>DynamoDB global secondary index - The resource type is <code>index</code> and the unique identifier is the resource ID. \n               Example: <code>table/my-table/index/my-table-index</code>.</p>\n           </li>\n            <li>\n               <p>Aurora DB cluster - The resource type is <code>cluster</code> and the unique identifier is the cluster name.\n               Example: <code>cluster:my-db-cluster</code>.</p>\n           </li>\n         </ul>", "smithy.api#required" => {}}))
    ScalingInstruction.add_member(:scalable_dimension, Smithy::Schema::Shapes::ShapeRef.new(shape: ScalableDimension, location_name: 'ScalableDimension', traits: {"smithy.api#documentation" => "<p>The scalable dimension associated with the resource.</p> \n         <ul>\n            <li>\n               <p>\n                  <code>autoscaling:autoScalingGroup:DesiredCapacity</code> - The desired capacity of an Auto Scaling group.</p>\n           </li>\n            <li>\n               <p>\n                  <code>ecs:service:DesiredCount</code> - The desired task count of an ECS service.</p>\n           </li>\n            <li>\n               <p>\n                  <code>ec2:spot-fleet-request:TargetCapacity</code> - The target capacity of a Spot Fleet request.</p>\n           </li>\n            <li>\n               <p>\n                  <code>dynamodb:table:ReadCapacityUnits</code> - The provisioned read capacity for a DynamoDB table.</p>\n           </li>\n            <li>\n               <p>\n                  <code>dynamodb:table:WriteCapacityUnits</code> - The provisioned write capacity for a DynamoDB table.</p>\n           </li>\n            <li>\n               <p>\n                  <code>dynamodb:index:ReadCapacityUnits</code> - The provisioned read capacity for a DynamoDB global secondary index.</p>\n           </li>\n            <li>\n               <p>\n                  <code>dynamodb:index:WriteCapacityUnits</code> - The provisioned write capacity for a DynamoDB global secondary index.</p>\n           </li>\n            <li>\n               <p>\n                  <code>rds:cluster:ReadReplicaCount</code> - The count of Aurora Replicas in an Aurora DB cluster. Available for Aurora MySQL-compatible edition and Aurora PostgreSQL-compatible edition.</p>\n           </li>\n         </ul>", "smithy.api#required" => {}}))
    ScalingInstruction.add_member(:min_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceCapacity, location_name: 'MinCapacity', traits: {"smithy.api#documentation" => "<p>The minimum capacity of the resource. </p>", "smithy.api#required" => {}}))
    ScalingInstruction.add_member(:max_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceCapacity, location_name: 'MaxCapacity', traits: {"smithy.api#documentation" => "<p>The maximum capacity of the resource. The exception to this upper limit is if you\n         specify a non-default setting for <b>PredictiveScalingMaxCapacityBehavior</b>. </p>", "smithy.api#required" => {}}))
    ScalingInstruction.add_member(:target_tracking_configurations, Smithy::Schema::Shapes::ShapeRef.new(shape: TargetTrackingConfigurations, location_name: 'TargetTrackingConfigurations', traits: {"smithy.api#documentation" => "<p>The target tracking configurations (up to 10). Each of these structures must specify a\n         unique scaling metric and a target value for the metric. </p>", "smithy.api#required" => {}}))
    ScalingInstruction.add_member(:predefined_load_metric_specification, Smithy::Schema::Shapes::ShapeRef.new(shape: PredefinedLoadMetricSpecification, location_name: 'PredefinedLoadMetricSpecification', traits: {"smithy.api#documentation" => "<p>The predefined load metric to use for predictive scaling. This parameter or a <b>CustomizedLoadMetricSpecification</b> is required when configuring\n         predictive scaling, and cannot be used otherwise. </p>"}))
    ScalingInstruction.add_member(:customized_load_metric_specification, Smithy::Schema::Shapes::ShapeRef.new(shape: CustomizedLoadMetricSpecification, location_name: 'CustomizedLoadMetricSpecification', traits: {"smithy.api#documentation" => "<p>The customized load metric to use for predictive scaling. This parameter or a <b>PredefinedLoadMetricSpecification</b> is required when configuring\n         predictive scaling, and cannot be used otherwise. </p>"}))
    ScalingInstruction.add_member(:scheduled_action_buffer_time, Smithy::Schema::Shapes::ShapeRef.new(shape: ScheduledActionBufferTime, location_name: 'ScheduledActionBufferTime', traits: {"smithy.api#documentation" => "<p>The amount of time, in seconds, to buffer the run time of scheduled scaling actions when\n         scaling out. For example, if the forecast says to add capacity at 10:00 AM, and the buffer\n         time is 5 minutes, then the run time of the corresponding scheduled scaling action will be\n         9:55 AM. The intention is to give resources time to be provisioned. For example, it can\n         take a few minutes to launch an EC2 instance. The actual amount of time required depends on\n         several factors, such as the size of the instance and whether there are startup scripts to\n         complete. </p>\n         <p>The value must be less than the forecast interval duration of 3600 seconds (60 minutes).\n         The default is 300 seconds. </p>\n         <p>Only valid when configuring predictive scaling. </p>"}))
    ScalingInstruction.add_member(:predictive_scaling_max_capacity_behavior, Smithy::Schema::Shapes::ShapeRef.new(shape: PredictiveScalingMaxCapacityBehavior, location_name: 'PredictiveScalingMaxCapacityBehavior', traits: {"smithy.api#documentation" => "<p>Defines the behavior that should be applied if the forecast capacity approaches or\n         exceeds the maximum capacity specified for the resource. The default value is\n            <code>SetForecastCapacityToMaxCapacity</code>.</p>\n         <p>The following are possible values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>SetForecastCapacityToMaxCapacity</code> - AWS Auto Scaling cannot scale resource\n               capacity higher than the maximum capacity. The maximum capacity is enforced as a hard\n               limit. </p>\n            </li>\n            <li>\n               <p>\n                  <code>SetMaxCapacityToForecastCapacity</code> - AWS Auto Scaling may scale resource\n               capacity higher than the maximum capacity to equal but not exceed forecast\n               capacity.</p>\n            </li>\n            <li>\n               <p>\n                  <code>SetMaxCapacityAboveForecastCapacity</code> - AWS Auto Scaling may scale resource\n               capacity higher than the maximum capacity by a specified buffer value. The intention\n               is to give the target tracking scaling policy extra capacity if unexpected traffic\n               occurs. </p>\n            </li>\n         </ul>\n         <p>Only valid when configuring predictive scaling.</p>"}))
    ScalingInstruction.add_member(:predictive_scaling_max_capacity_buffer, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceCapacity, location_name: 'PredictiveScalingMaxCapacityBuffer', traits: {"smithy.api#documentation" => "<p>The size of the capacity buffer to use when the forecast capacity is close to or exceeds\n         the maximum capacity. The value is specified as a percentage relative to the forecast\n         capacity. For example, if the buffer is 10, this means a 10 percent buffer, such that if\n         the forecast capacity is 50, and the maximum capacity is 40, then the effective maximum\n         capacity is 55.</p>\n         <p>Only valid when configuring predictive scaling. Required if the <b>PredictiveScalingMaxCapacityBehavior</b> is set to\n            <code>SetMaxCapacityAboveForecastCapacity</code>, and cannot be used otherwise.</p>\n         <p>The range is 1-100.</p>"}))
    ScalingInstruction.add_member(:predictive_scaling_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: PredictiveScalingMode, location_name: 'PredictiveScalingMode', traits: {"smithy.api#documentation" => "<p>The predictive scaling mode. The default value is <code>ForecastAndScale</code>.\n         Otherwise, AWS Auto Scaling forecasts capacity but does not create any scheduled scaling actions\n         based on the capacity forecast. </p>"}))
    ScalingInstruction.add_member(:scaling_policy_update_behavior, Smithy::Schema::Shapes::ShapeRef.new(shape: ScalingPolicyUpdateBehavior, location_name: 'ScalingPolicyUpdateBehavior', traits: {"smithy.api#documentation" => "<p>Controls whether a resource's externally created scaling policies are kept or replaced. </p>\n         <p>The default value is <code>KeepExternalPolicies</code>. If the parameter is set to\n            <code>ReplaceExternalPolicies</code>, any scaling policies that are external to AWS Auto Scaling\n         are deleted and new target tracking scaling policies created. </p>\n         <p>Only valid when configuring dynamic scaling. </p>\n         <p>Condition: The number of existing policies to be replaced must be less than or equal to\n         50. If there are more than 50 policies to be replaced, AWS Auto Scaling keeps all existing policies\n         and does not create new ones.</p>"}))
    ScalingInstruction.add_member(:disable_dynamic_scaling, Smithy::Schema::Shapes::ShapeRef.new(shape: DisableDynamicScaling, location_name: 'DisableDynamicScaling', traits: {"smithy.api#documentation" => "<p>Controls whether dynamic scaling by AWS Auto Scaling is disabled. When dynamic scaling is\n         enabled, AWS Auto Scaling creates target tracking scaling policies based on the specified target\n         tracking configurations. </p>\n         <p>The default is enabled (<code>false</code>). </p>"}))
    ScalingInstruction.type = Types::ScalingInstruction
